// --- Edge case tests ---

tape( 'the function leaves output unchanged when `N` is equal to zero', function test( t ) {
	var iseed;
	var data;
	var x;

	data = IDIST1_SMALL;

	iseed = new Int32Array( data.ISEED );
	x = new Float64Array( data.X );

	dlarnv( 1, iseed, data.strideISEED, data.offsetISEED, 0, x, data.strideX, data.offsetX );
	t.deepEqual( x, new Float64Array( data.X ), 'returns expected value' );
	t.deepEqual( iseed, new Int32Array( data.ISEED ), 'returns expected value' );

	t.end();
});

tape( 'the function generates values in the open interval (0,1) for idist=1', function test( t ) {
	var iseed;
	var x;
	var i;

	iseed = new Int32Array( [ 100, 200, 300, 401 ] );
	x = new Float64Array( 100 );

	dlarnv( 1, iseed, 1, 0, 100, x, 1, 0 );

	for ( i = 0; i < x.length; i++ ) {
		t.ok( x[ i ] > 0.0 && x[ i ] < 1.0, 'value at index ' + i + ' is in (0,1): ' + x[ i ] );
	}

	t.end();
});

tape( 'the function generates values in the open interval (-1,1) for idist=2', function test( t ) {
	var iseed;
	var x;
	var i;

	iseed = new Int32Array( [ 100, 200, 300, 401 ] );
	x = new Float64Array( 100 );

	dlarnv( 2, iseed, 1, 0, 100, x, 1, 0 );

	for ( i = 0; i < x.length; i++ ) {
		t.ok( x[ i ] > -1.0 && x[ i ] < 1.0, 'value at index ' + i + ' is in (-1,1): ' + x[ i ] );
	}

	t.end();
});
